from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class BtsInfoV1(SchemaObject):
    status = SchemaField(name="status")
    name = SchemaField(name="name")
    btsid = SchemaField(name="bts_id")
    numberofAlarms = SchemaField(name="number_of_alarms")

    def __init__(self, status=None, name=None, btsid=None, numberofAlarms=None):
        self.status = status
        self.name = name
        self.btsid = btsid
        self.numberofAlarms = numberofAlarms

        super(BtsInfoV1, self).__init__()
